/**
 * Sai Krishna Homes: projects, amenities and gallery content.
 * Photos live in /public/images (generated by scripts/optimize-photos.mjs):
 *   <name>.webp (max 2400px, full screen / lightbox)  ·  <name>-sm.webp (900px, cards / thumbnails)
 * Only facts confirmed by the client's existing site or photos are written here. Add prices, carpet
 * areas and RERA numbers once the client provides them.
 */

/** Build the large + small URLs for a photo in /public/images. */
export const photo = (name, alt) => ({ src: `/images/${name}.webp`, sm: `/images/${name}-sm.webp`, alt });

/**
 * Responsive image props: phones download the 900px file, larger screens the 2400px one.
 * Usage: <img {...responsive(photo, '100vw')} />
 */
export const responsive = (p, sizes = '100vw') => ({
  src: p.src,
  srcSet: `${p.sm} 900w, ${p.src} 2400w`,
  sizes,
  alt: p.alt,
});

